import React from "react";
import Operator from "./Operator";
import FractionDisplay from "./FractionDisplay";
import Parentheses from "./Parentheses";
import FractionInput from "./FractionInput";

const CompoundFraction = ({
  // Display props
  leftNumerator = "",
  leftDenominator = "",
  operator = "×",
  rightNumber = "",
  rightNumerator = "",
  rightDenominator = "",

  // Input values
  numerator1Value = null,
  denominator1Value = null,
  numerator2Value = null,
  denominator2Value = null,
  numerator3Value = null,
  denominator3Value = null,
  inputsNumValue = null,
  inputsDenomValue = null,

  // Input handlers
  onNumerator1Change = () => {},
  onDenominator1Change = () => {},
  onNumerator2Change = () => {},
  onDenominator2Change = () => {},
  onNumerator3Change = () => {},
  onDenominator3Change = () => {},
  onInputsNumChange = () => {},
  onInputsDenomChange = () => {},

  // Other props
  mathInputNull,
  setMathInputNull,
}) => {
  return (
    <div className="flex flex-col pl-2 md:pl-0">
      {/* Part 1 - Static display */}
      <div className="flex flex-col md:flex-row">
        <div className="part-1 md:pt-[6px]">
          <table className="digit">
            <tr>
              <td className="flex flex-row items-center">
                <FractionDisplay
                  numerator={leftNumerator}
                  denominator={leftDenominator}
                />
                <Operator symbol={operator} className="mx-3 md:mx-6" />
                <table className="3rd col mr-1 md:mr-2">
                  <tbody>
                    <tr>
                      <td>{rightNumber}</td>
                    </tr>
                  </tbody>
                </table>
                <FractionDisplay
                  numerator={rightNumerator}
                  denominator={rightDenominator}
                />
                <Operator symbol="=" className="mx-3 md:mx-6" />
              </td>
            </tr>
          </table>
        </div>

        {/* Part 2 - Input section */}
        <div className="part-2 flex flex-row mt-8 md:mt-0">
          <Operator
            symbol="="
            className="mr-2 md:mr-4 flex items-center md:hidden"
          />
          <table className="digit">
            <tr>
              <td className="flex flex-row items-center">
                <FractionDisplay
                  numerator={leftNumerator}
                  denominator={leftDenominator}
                />
                <Operator symbol={operator} className="mx-2 md:mx-4" />
                <Parentheses type="(" className="mr-2 md:mr-4 h-[100px]" />
                <FractionInput
                  numeratorValue={numerator1Value}
                  denominatorValue={denominator1Value}
                  onNumeratorChange={onNumerator1Change}
                  onDenominatorChange={onDenominator1Change}
                />
                <Operator symbol="+" className="mx-2 md:mx-4" />
                <FractionInput
                  numeratorValue={numerator2Value}
                  denominatorValue={denominator2Value}
                  onNumeratorChange={onNumerator2Change}
                  onDenominatorChange={onDenominator2Change}
                />
                <Parentheses type=")" className="ml-2 md:ml-4 h-[100px]" />
                <Operator symbol="=" className="mx-3 md:mx-6" />
              </td>
            </tr>
          </table>
        </div>
      </div>

      {/* Bottom row */}
      <div className="bottom-row mt-8 md:mt-16">
        <table className="digit">
          <tr>
            <td className="flex flex-row items-center">
              <Operator symbol="=" className="mr-3 md:mr-6" />
              <FractionDisplay
                numerator={leftNumerator}
                denominator={leftDenominator}
              />
              <Operator symbol={operator} className="mx-3 md:mx-6" />
              <FractionInput
                numeratorValue={numerator3Value}
                denominatorValue={denominator3Value}
                onNumeratorChange={onNumerator3Change}
                onDenominatorChange={onDenominator3Change}
              />
              <Operator symbol="=" className="mx-2 md:mx-4" />
              <FractionInput
                numeratorValue={inputsNumValue}
                denominatorValue={inputsDenomValue}
                onNumeratorChange={onInputsNumChange}
                onDenominatorChange={onInputsDenomChange}
              />
            </td>
          </tr>
        </table>
      </div>
    </div>
  );
};

export default CompoundFraction;
